/**
 * PDP gallery panels, as HTML.
 *
 * Rendered to PNG by build.mjs rather than generated by an image model. These
 * panels are almost entirely TYPE — a nutrition table, bullet lists, a
 * comparison chart — and a generative model cannot set type reliably: earlier
 * attempts came back with text too small to read and words it invented. Here
 * the copy is exactly the copy in data.mjs, at a size chosen in points, in the
 * real brand faces.
 *
 * Every panel is a 1200×1200 square, matching how a PDP gallery is shown.
 */
import { COLOR, BRAND } from "./data.mjs";

const S = 1200;

/**
 * The botanical wash behind every panel.
 *
 * Drawn as an SVG pattern rather than placed as a photo so it stays crisp at
 * any export size and carries no third-party asset.
 */
function botanical(opacity = 0.5, stroke = "#D9CFA8") {
  /*
   * A single large FARM SCENE, not a small repeating tile.
   *
   * The first version tiled a ~200px leaf motif across the canvas. Repeated at
   * that scale it reads as wallpaper — busy up close, invisible in a thumbnail,
   * and flat either way. The reference works because its backdrop is drawn once
   * at canvas scale: a sun in one corner, a few big trees, wheat along the
   * bottom, a grazing animal. Elements are placed away from the centre so they
   * sit behind the content instead of fighting it.
   */
  const o = opacity;
  const tree = (x, y, s) => `
    <g transform="translate(${x},${y}) scale(${s})" opacity="${o * 0.85}">
      <path d="M0 200 L0 120" stroke="${stroke}" stroke-width="5" fill="none"/>
      <path d="M0 150 L-30 120 M0 150 L30 120 M0 176 L-22 152 M0 176 L22 152"
            stroke="${stroke}" stroke-width="3.5" fill="none"/>
      <path d="M0 130 C -78 130, -96 46, -40 22 C -30 -22, 30 -22, 40 22
               C 96 46, 78 130, 0 130 Z"
            stroke="${stroke}" stroke-width="4" fill="none"/>
      <path d="M-46 62 q 22 -16 44 0 M-30 96 q 20 -14 40 0 M-16 34 q 16 -12 32 0"
            stroke="${stroke}" stroke-width="2.6" fill="none"/>
    </g>`;

  const wheat = (x, y, s) => `
    <g transform="translate(${x},${y}) scale(${s})" opacity="${o * 0.8}"
       stroke="${stroke}" stroke-width="3" fill="none">
      <path d="M0 130 L0 30"/>
      <path d="M0 44 q 18 -10 22 -28 q -20 2 -22 28 Z"/>
      <path d="M0 44 q -18 -10 -22 -28 q 20 2 22 28 Z"/>
      <path d="M0 72 q 18 -10 22 -28 q -20 2 -22 28 Z"/>
      <path d="M0 72 q -18 -10 -22 -28 q 20 2 22 28 Z"/>
      <path d="M0 100 q 18 -10 22 -28 q -20 2 -22 28 Z"/>
      <path d="M0 100 q -18 -10 -22 -28 q 20 2 22 28 Z"/>
    </g>`;

  const sun = (x, y, s) => {
    const rays = Array.from({ length: 14 }, (_, i) => {
      const a = (Math.PI * 2 * i) / 14;
      const x1 = Math.cos(a) * 92, y1 = Math.sin(a) * 92;
      const x2 = Math.cos(a) * 128, y2 = Math.sin(a) * 128;
      return `<path d="M${x1.toFixed(1)} ${y1.toFixed(1)} L${x2.toFixed(1)} ${y2.toFixed(1)}"/>`;
    }).join("");
    return `
      <g transform="translate(${x},${y}) scale(${s})" opacity="${o * 0.9}"
         stroke="${stroke}" stroke-width="5" fill="none" stroke-linecap="round">
        <circle cx="0" cy="0" r="72"/>${rays}
      </g>`;
  };

  /* A grazing cow, low and small — a farm cue, never a focal point. */
  const cow = (x, y, s) => `
    <g transform="translate(${x},${y}) scale(${s})" opacity="${o * 0.55}"
       stroke="${stroke}" stroke-width="3.4" fill="none" stroke-linejoin="round">
      <path d="M-60 0 q 6 -34 40 -34 h44 q 30 0 34 30 l4 24"/>
      <path d="M-60 0 l-4 26 M-24 -4 l-2 30 M22 -4 l2 30 M58 0 l4 26"/>
      <path d="M-60 -6 q -18 -4 -24 -20 q 14 -4 24 6"/>
      <path d="M62 -30 q 12 -12 22 -6"/>
    </g>`;

  const leaflet = (x, y, s, rot = 0) => `
    <g transform="translate(${x},${y}) rotate(${rot}) scale(${s})" opacity="${o * 0.6}"
       stroke="${stroke}" stroke-width="3" fill="none">
      <path d="M0 0 C 30 26, 30 74, 0 100 C -30 74, -30 26, 0 0 Z"/>
      <path d="M0 8 L0 92"/>
      <path d="M0 34 q 18 8 24 20 M0 34 q -18 8 -24 20 M0 62 q 16 8 20 18 M0 62 q -16 8 -20 18"/>
    </g>`;

  return `
    <svg viewBox="0 0 ${S} ${S}" width="100%" height="100%"
         xmlns="http://www.w3.org/2000/svg"
         preserveAspectRatio="xMidYMid slice"
         style="position:absolute;inset:0;z-index:0">
      ${sun(148, 132, 1.05)}
      ${tree(1052, 236, 1.5)}
      ${tree(96, 812, 1.25)}
      ${tree(1108, 900, 1.1)}
      ${wheat(322, 1010, 1.15)}
      ${wheat(408, 1042, 0.9)}
      ${wheat(884, 1024, 1.05)}
      ${cow(700, 1112, 1.0)}
      ${leaflet(980, 560, 0.95, 24)}
      ${leaflet(178, 470, 0.8, -18)}
      ${leaflet(560, 122, 0.7, 8)}
    </svg>`;
}

/**
 * The farm scene as a drop-in layer.
 *
 * Panels whose own content paints a solid background — the comparison halves —
 * cover the shell's backdrop entirely. They re-inject it inside each half, in a
 * stroke colour that reads against that half.
 */
export function backdrop(opacity, stroke) {
  return botanical(opacity, stroke);
}

/** Shared page chrome. `bg` and the pattern tint switch for dark panels. */
function shell(inner, { bg = COLOR.cream, dark = false } = {}) {
  return `
  <div class="panel" style="background:${bg}">
    ${botanical(dark ? 0.16 : 0.5, dark ? "#4E7A58" : "#D9CFA8")}
    <div class="content">${inner}</div>
  </div>`;
}

/* ── 1 · Nutrition facts ─────────────────────────────────────────────── */

/** A value that may be provisional: `{ value, coa }` or a plain number. */
const val = (v) => (typeof v === "object" && v !== null ? v.value : v);
const rda = (v) => (typeof v === "object" && v !== null ? (v.rda ?? "") : "");
const certified = (v) => !(typeof v === "object" && v !== null && v.coa === false);

export function nutritionPanel(p, size = "1L") {
  const n = p.nutrition;
  const servings = n.servingsPerContainer?.[size] ?? "";
  const isOil = p.category === "oils";

  const row = (label, value, pct, { indent = 0, bold = false, sub = false } = {}) => `
    <tr class="${bold ? "b" : ""} ${sub ? "sub" : ""}">
      <td style="padding-left:${indent * 16}px">${label}</td>
      <td class="pct">${pct ?? ""}</td>
    </tr>`;

  const anyProvisional = [n.saturatedFatG, n.mufaG, n.pufaG, n.vitaminEMg, n.vitaminAMcg, n.cholesterolMg]
    .some((f) => f !== undefined && !certified(f));

  const rows = [
    row(`<b>CALORIES</b> (${n.caloriesKcal} kcal)`, null, n.caloriesRda, { bold: true }),
    row(`<b>Total Fat</b> (${n.totalFatG}g)`, null, n.totalFatRda, { bold: true }),
    row(`Saturated Fat (${val(n.saturatedFatG)}g)`, null, rda(n.saturatedFatG), { indent: 1 }),
    row(`Trans fat (${n.transFatG}g)`, null, "", { indent: 1 }),
    row(`MUFA (${val(n.mufaG)}g)`, null, "", { indent: 1 }),
    row(`PUFA (${val(n.pufaG)}g)`, null, "", { indent: 1 }),
    row(`<b>Cholesterol</b> (${val(n.cholesterolMg)}mg)`, null, rda(n.cholesterolMg) || "0%", { bold: true }),
    row(`<b>Sodium</b> (${n.sodiumMg}mg)`, null, "0%", { bold: true }),
    row(`<b>Total Carbohydrates</b> (${n.carbsG}g)`, null, "0%", { bold: true }),
    row(`Dietary Fibre (${n.fibreG}g)`, null, "0%", { indent: 1 }),
    row(`Total Sugar (${n.sugarG}g)`, null, "", { indent: 1 }),
    row(`Includes ${n.addedSugarG}g Added Sugars`, null, "0%", { indent: 2 }),
    row(`<b>Protein</b> (${n.proteinG}g)`, null, "0%", { bold: true }),
    isOil
      ? row(`<b>Vitamin E</b> (${val(n.vitaminEMg)}mg)`, null, rda(n.vitaminEMg), { bold: true })
      : row(`<b>Vitamin A</b> (${val(n.vitaminAMcg)}mcg)`, null, rda(n.vitaminAMcg), { bold: true }),
  ].join("");

  const inner = `
    <div class="nut-wrap">
      <div class="nut-card">
        <div class="nut-head">NUTRITION FACTS</div>
        <div class="nut-servings">${servings} Servings per container</div>
        <table class="nut">
          <tr class="hdr"><td>Serving size</td><td class="pct">${n.servingLabel}</td></tr>
          <tr class="hdr2"><td>Amount Per Serving</td><td class="pct">% RDA/Serve*</td></tr>
          ${rows}
        </table>
        <div class="nut-foot">
          *The % RDA tells you how much a nutrient in a serving of food contributes to a
          daily diet. 2,000 calories a day is used for general nutrition advice.
          ${anyProvisional ? "<br><br>Typical values. Batch figures may vary." : ""}
        </div>
      </div>
      <div class="nut-bottle"><img src="${p.bottle}" alt=""></div>
    </div>`;
  return shell(inner);
}

/* ── 2 · Only one ingredient ─────────────────────────────────────────── */

export function ingredientPanel(p) {
  const inner = `
    <div class="ing">
      <div class="ing-bottle"><img src="${p.bottle}" alt=""></div>
      <div class="ing-copy">
        <h1 class="ing-h">${p.ingredientPanel.heading}</h1>
        <ul class="ing-list">
          ${p.ingredientPanel.bullets.map((b) => `<li>${b}</li>`).join("")}
        </ul>
      </div>
    </div>`;
  return shell(inner);
}

/* ── 3 · Sourcing story ──────────────────────────────────────────────── */

export function sourcingPanel(p, heroImg) {
  const s = p.sourcing;
  const inner = `
    <div class="src">
      <div class="src-photo" style="background-image:url('${heroImg}')"></div>
      <div class="src-box">
        <p class="src-lead">${s.lead}</p>
        ${s.body.map((l) => `<p class="src-line">${l}</p>`).join("")}
        <p class="src-region">${s.region}</p>
      </div>
    </div>`;
  return shell(inner);
}

/* ── 4 · How to use ──────────────────────────────────────────────────── */

/*
 * Photo tiles when the product has kitchen photography, drawn marks when it
 * does not.
 *
 * Ghee has no action shots yet, and the only ghee images to hand are existing
 * infographics — dropping one into a tile would nest an infographic inside an
 * infographic, with its own competing captions. So the icon path stays as the
 * honest fallback rather than being deleted.
 */
const USE_ICONS = {
  Drizzle: `<path d="M20 6c0 0-7 3-7 8"/><path d="M13 14v3"/><path d="M6 20h12"/><path d="M6 20a6 6 0 0 1 12 0"/>`,
  "Stir-Fry": `<path d="M3 12h14a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z"/><path d="M17 13l4-3"/><path d="M7 8c0-2 2-2 2-4"/><path d="M12 8c0-2 2-2 2-4"/>`,
  "Deep-Fry": `<path d="M4 11h14v3a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5v-3Z"/><path d="M18 12h3"/><circle cx="8" cy="7" r="1.4"/><circle cx="13" cy="5.5" r="1.4"/>`,
  Tempering: `<path d="M5 13h12a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4Z"/><path d="M17 14l4-2"/><path d="M9 9c0-2 2-2 2-4"/>`,
  "Everyday Roti": `<circle cx="12" cy="12" r="8"/><path d="M9 10.5c1.5 1 3.5 1 5 0"/><circle cx="10" cy="14" r=".9"/><circle cx="14" cy="13.6" r=".9"/>`,
  Sweets: `<path d="M12 4l2.2 4.6 5 .7-3.6 3.5.9 5-4.5-2.4L7.5 17.8l.9-5L4.8 9.3l5-.7Z"/>`,
};

export function usagePanel(p, hasPhotos = false) {
  const photoTile = (m) => `
    <div class="use-tile photo">
      <div class="use-img" style="background-image:url('${m.img}')"></div>
      <div class="use-label">${m.label}</div>
    </div>`;

  const iconTile = (m) => `
    <div class="use-tile">
      <div class="use-mark">
        <svg viewBox="0 0 24 24" fill="none" stroke="${COLOR.forestSoft}" stroke-width="1.4"
             stroke-linecap="round" stroke-linejoin="round">
          ${USE_ICONS[m.label] ?? USE_ICONS.Drizzle}
        </svg>
      </div>
      <div class="use-label">${m.label}</div>
    </div>`;

  const tile = hasPhotos ? photoTile : iconTile;
  const inner = `
    <div class="use">
      <h2 class="use-h">How to use it</h2>
      <div class="use-row">${p.usage.modes.map(tile).join("")}</div>
      <div class="use-notes">
        ${p.usage.notes.map((n) => `<p>• ${n}</p>`).join("")}
      </div>
    </div>`;
  return shell(inner);
}

/* ── 5 · Clean product shot ──────────────────────────────────────────── */

export function heroPanel(p) {
  const inner = `
    <div class="hero">
      <img src="${p.bottle}" alt="">
      <div class="hero-mark">${BRAND.wordmark}</div>
    </div>`;
  return shell(inner, { bg: COLOR.paper });
}

/* ── 6 · Cold-pressed vs refined ─────────────────────────────────────── */

export function comparisonPanel(p) {
  const c = p.comparison;
  /*
   * The bottle is split down the middle, not simply centred.
   *
   * The same bottle appears twice, clipped to each half: the left keeps its
   * true golden colour, the right is desaturated and paled to stand for refined
   * oil. That single image carries the whole argument — "vibrant colour" versus
   * "uniform pale colour" — which a centred bottle cannot.
   */
  const inner = `
    <div class="cmp">
      <div class="cmp-half left">
        ${botanical(0.3, "#7FA789")}
        <div class="cmp-pill light">${c.left.title}</div>
        <ul>${c.left.points.map((x) => `<li>${x}</li>`).join("")}</ul>
      </div>
      <div class="cmp-half right">
        ${botanical(0.42, "#D9CFA8")}
        <div class="cmp-pill dark">${c.right.title}</div>
        <ul>${c.right.points.map((x) => `<li>${x}</li>`).join("")}</ul>
      </div>
      <div class="cmp-bottle">
        <div class="cmp-b-half l"><img src="${p.bottle}" alt=""></div>
        <div class="cmp-b-half r"><img src="${p.bottle}" alt=""></div>
      </div>
    </div>`;
  return shell(inner, { bg: COLOR.cream });
}

/* ── 7 · Benefits ────────────────────────────────────────────────────── */

const ICONS = {
  press: `<path d="M7 4h10v4H7z"/><path d="M12 8v5"/><path d="M9 20h6a3 3 0 0 0-3-3 3 3 0 0 0-3 3Z"/>`,
  drop: `<path d="M12 3s6 6.6 6 10.5A6 6 0 0 1 6 13.5C6 9.6 12 3 12 3Z"/>`,
  heart: `<path d="M12 20s-7-4.5-7-9.3A3.9 3.9 0 0 1 12 8a3.9 3.9 0 0 1 7 2.7C19 15.5 12 20 12 20Z"/><path d="M4 13h4l1.5-3 2 5 1.5-2h7"/>`,
  shield: `<path d="M12 3l7 3v5c0 4.5-3 8-7 10-4-2-7-5.5-7-10V6Z"/><path d="M9 12l2 2 4-4"/>`,
};

export function benefitsPanel(p, bowlImg) {
  const b = p.benefits;
  const badge = (it) => `
    <div class="ben-item">
      <div class="ben-icon">
        <svg viewBox="0 0 24 24" fill="none" stroke="${COLOR.cream}" stroke-width="1.5"
             stroke-linecap="round" stroke-linejoin="round">${ICONS[it.icon]}</svg>
      </div>
      <div class="ben-label">${it.label.replace(/\n/g, "<br>")}</div>
    </div>`;
  const inner = `
    <div class="ben">
      <div class="ben-head">
        <div class="ben-title">${b.heading.map((l) => `<span>${l}</span>`).join("")}</div>
        <div class="ben-bowl" style="background-image:url('${bowlImg}')"></div>
      </div>
      <div class="ben-grid">${b.items.map(badge).join("")}</div>
    </div>`;
  return shell(inner);
}

